#pragma once
#include "../../support.hpp"
namespace algs {
class LazySegmentTree{int n;Numbers sums,pending;void assertRange(int l,int r)const{if(l<0||r>=n||l>r)throw std::out_of_range("Invalid range");}void build(int node,int s,int e,const Numbers&a){if(s==e){sums[node]=a[s];return;}int m=(s+e)/2;build(2*node,s,m,a);build(2*node+1,m+1,e,a);sums[node]=sums[2*node]+sums[2*node+1];}void apply(int node,int s,int e,double d){sums[node]+=d*(e-s+1);pending[node]+=d;}void push(int node,int s,int e){double d=pending[node];if(d==0||s==e)return;int m=(s+e)/2;apply(2*node,s,m,d);apply(2*node+1,m+1,e,d);pending[node]=0;}void add(int node,int s,int e,int l,int r,double d){if(r<s||e<l)return;if(l<=s&&e<=r){apply(node,s,e,d);return;}push(node,s,e);int m=(s+e)/2;add(2*node,s,m,l,r,d);add(2*node+1,m+1,e,l,r,d);sums[node]=sums[2*node]+sums[2*node+1];}double sum(int node,int s,int e,int l,int r){if(r<s||e<l)return 0;if(l<=s&&e<=r)return sums[node];push(node,s,e);int m=(s+e)/2;return sum(2*node,s,m,l,r)+sum(2*node+1,m+1,e,l,r);}public:explicit LazySegmentTree(const Numbers&a):n(int(a.size())),sums(4*std::max(1,n)),pending(sums.size()){if(n)build(1,0,n-1,a);}int size()const{return n;}void rangeAdd(int l,int r,double d){assertRange(l,r);add(1,0,n-1,l,r,d);}double rangeSum(int l,int r){assertRange(l,r);return sum(1,0,n-1,l,r);}};
}
